import{_ as i,a0 as l,w as r,s as c,ao as d,I as o,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"watch：定期重複Linux / Unix命令 | LCTT x X-CMD","titleTemplate":false,"description":"watch：定期重複Linux / Unix命令 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"watch：定期重複Linux / Unix命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"watch：定期重複Linux / Unix命令 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150610 watch--Repeat Linux or Unix Commands Regular Intervals","title":"watch：定期重複Linux / Unix命令","tag":"201507","desc":""},"relativePath":"201507/20150610 watch--Repeat Linux or Unix Commands Regular Intervals.md","filePath":"[post].md"}'),s={name:"201507/20150610 watch--Repeat Linux or Unix Commands Regular Intervals.md"};function h(m,t,x,u,w,g){const a=l("Link");return r(),c("div",null,[t[13]||(t[13]=d(`<h1 id="watch-定期重複linux-unix命令" tabindex="-1">watch：定期重複Linux / Unix命令 <a class="header-anchor" href="#watch-定期重複linux-unix命令" aria-label="Permalink to “watch：定期重複Linux / Unix命令”">​</a></h1><p>服務器管理員需要維護系統並保持更新和安全。每天需要運行大量的指令。有些系統進程會記錄日誌。這些日誌不斷更新。為了檢查這些更新，需要重複地執行命令。比如，為了讀取一個日誌文件需要使用head、tail、cat等命令。這些命令需要重複地執行。而watch命令可以用於定期地執行一個命令。</p><h3 id="watch-命令" tabindex="-1">Watch 命令 <a class="header-anchor" href="#watch-命令" aria-label="Permalink to “Watch 命令”">​</a></h3><p>watch是一個簡單的命令，只有幾個選項。watch命令的基本語法是：</p><pre><code>watch [-dhvt] [-n &lt;seconds&gt;] [--differences[=cumulative]] [--help] [--interval=&lt;seconds&gt;] [--no-title] [--version] &lt;command&gt;
</code></pre><p>watch命令默認每隔2秒執行後面參數給出的命令。這個時間根據的是命令執行結束到上次執行的間隔來算的。比如，watch命令可以用於監測日誌更新，更新是在文件的後面追加新的內容，因此可以用tail命令來檢測文件的更新（LCTT 譯註：可以直接使用 <code>tail -f</code> 主動跟蹤某個文件的更新，而不用使用 watch。）。這個命令會持續地運行直到你按下 <code>CTRL + C</code>回到提示符。</p><h3 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to “例子”">​</a></h3><p>每兩秒監測 errors/notices/warning 生成的情況。</p><pre><code>watch tail /var/log/messages
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/1.png" alt="tail messages"></p><p>按指定的時間間隔監測磁盤的使用率。</p><pre><code>watch df -h
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/2.png" alt="df -h"></p><p>對磁盤管理員而言，關注高I/O等待導致的磁盤操作尤其是mysql事務是很重要的。</p><pre><code>watch mysqladmin processlist
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/3.png" alt="processlist"></p><p>監測服務器負載和運行時間。</p><pre><code>watch uptime
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/10.png" alt="uptime"></p><p>監測exim給用户發送通知的隊列大小。</p><pre><code>watch exim -bpc
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/9.png" alt="exim -bpc"></p><h3 id="_1-指定延遲" tabindex="-1">1) 指定延遲 <a class="header-anchor" href="#_1-指定延遲" aria-label="Permalink to “1) 指定延遲”">​</a></h3><pre><code>watch [-n &lt;seconds&gt;] &lt;command&gt;
</code></pre><p>命令默認運行的時間間隔可用-n改變，下面的命令會在5秒後運行後面的命令：</p><pre><code>watch -n 5 date
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/4b.png" alt="date 5 seconds"></p><h3 id="_2-連續輸出比較" tabindex="-1">2) 連續輸出比較### <a class="header-anchor" href="#_2-連續輸出比較" aria-label="Permalink to “2) 連續輸出比較###”">​</a></h3><p>如果你使用-d選項，它會累次地高亮第一次和下一次命令之間輸出的差別。</p><pre><code>watch [-d or --differences[=cumulative]] &lt;command&gt;
</code></pre><p>例子 1，用下面的命令連續地輸出時間並觀察高亮出來的不同部分。</p><pre><code>watch -n 15 -d date
</code></pre><p>第一次執行date的輸出會被記錄，15秒後會重複運行命令。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/6.png" alt="Difference A"></p><p>在下一次執行時，可以看到輸出除了被高亮的秒數從14到29之外其他的都一樣。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/6b.png" alt="Difference A"></p><p>例子 2，讓我們來體驗一下兩個連續的“uptime”命令輸出的不同。</p><pre><code>watch -n 20 -d uptime
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/10.png" alt="uptime"></p><p>現在列出了時間和3個負載快照之間的不同。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/10b.png" alt="10b"></p><h3 id="_3-不帶標題輸出" tabindex="-1">3) 不帶標題輸出 <a class="header-anchor" href="#_3-不帶標題輸出" aria-label="Permalink to “3) 不帶標題輸出”">​</a></h3><p>如果你不希望顯示更多關於延遲和實際命令的信息可以使用-t選項。</p><pre><code>watch [-t or --no-title] &lt;command&gt;
</code></pre><p>讓我們看下下面例子命令的輸出：</p><pre><code>watch -t date
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/7t.png" alt="watch without title"></p><h3 id="watch-幫助" tabindex="-1">Watch 幫助 <a class="header-anchor" href="#watch-幫助" aria-label="Permalink to “Watch 幫助”">​</a></h3><p>可以在ssh中輸入下面的命令來得到watch的簡要幫助。</p><pre><code>watch -h [or --help]
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/8h.png" alt="watch help"></p><h3 id="watch-版本" tabindex="-1">Watch 版本 <a class="header-anchor" href="#watch-版本" aria-label="Permalink to “Watch 版本”">​</a></h3><p>在ssh終端中運行下面的命令來檢查watch的版本。</p><pre><code>watch -v [--version]
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/11.png" alt="version"></p><p><strong>不足</strong></p><p>不幸的是，在終端大小調整時，屏幕不能在下次運行前重畫。所有用--difference高亮的內容也會在更新時丟失。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>watch對系統管理員而言是一個非常強大的工具，因為它可以用於監控、日誌、運維、性能和系統運行時的吞吐量。人們可以非常簡單地格式化和推延watch的輸出。任何Linux命令/程序或腳本可以按照所需監測和連續輸出。</p><hr>`,60)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),n(a,{href:"http://linoxide.com/linux-command/linux-watch-command/"},{default:p(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/linux-watch-command/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),n(a,{href:"http://linoxide.com/author/arunrz/"},{default:p(()=>[...t[2]||(t[2]=[e("Aun Raza",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:p(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const L=i(s,[["render",h]]);export{T as __pageData,L as default};
